precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_cornerRadius;
uniform float u_blur;
uniform float u_refraction;
uniform vec2 u_resolution;

float sdRoundedBox(vec2 p, vec2 b, float r) {
    vec2 q = abs(p) - b + r;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}

vec2 computeRefraction(vec2 uv, vec2 size, float radius) {
    vec2 p = (uv - 0.5) * size;
    vec2 b = size * 0.5;
    float d = sdRoundedBox(p, b, radius);
    float eps = 3.0;
    float dx = sdRoundedBox(p + vec2(eps, 0.0), b, radius) - sdRoundedBox(p - vec2(eps, 0.0), b, radius);
    float dy = sdRoundedBox(p + vec2(0.0, eps), b, radius) - sdRoundedBox(p - vec2(0.0, eps), b, radius);
    vec2 grad = vec2(dx, dy) / (2.0 * eps);
    float edgeFade = 1.0 - smoothstep(0.0, radius * 1.5, -d);
    return grad * edgeFade;
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    vec2 uv = v_texCoord;
    vec2 panelUV = (uv - 0.5) * vec2(1.4, 1.2) + 0.5;
    vec2 panelSize = vec2(280.0, 200.0);
    float radius = u_cornerRadius * 40.0 + 5.0;

    vec2 p = (panelUV - 0.5) * panelSize;
    vec2 b = panelSize * 0.5;
    float d = sdRoundedBox(p, b, radius);
    float mask = 1.0 - smoothstep(-1.5, 1.5, d);

    // Background pattern
    vec3 bg = vec3(0.04, 0.06, 0.08);
    float t = u_time * 0.3;
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        vec2 center = vec2(0.5 + 0.35 * sin(t + fi * 1.1), 0.5 + 0.35 * cos(t * 0.8 + fi * 0.9));
        float dist = length(uv - center);
        vec3 col = vec3(0.18 + fi * 0.08, 0.6 - fi * 0.05, 0.75 - fi * 0.08);
        bg += col * 0.25 * smoothstep(0.3, 0.0, dist);
    }

    if (mask < 0.001) {
        gl_FragColor = vec4(bg, 1.0);
        return;
    }

    // Refraction
    vec2 refract = computeRefraction(panelUV, panelSize, radius);
    vec2 offset = -refract * u_refraction * 0.15;

    // Fake blur by averaging nearby samples
    vec3 glassColor = vec3(0.0);
    float blurSize = u_blur * 0.05;
    float total = 0.0;
    for (int x = -2; x <= 2; x++) {
        for (int y = -2; y <= 2; y++) {
            vec2 off = vec2(float(x), float(y)) * blurSize;
            float w = 1.0 / (1.0 + length(off) * 5.0);
            vec2 sampleUV = uv + offset + off;

            vec3 sample_bg = vec3(0.04, 0.06, 0.08);
            for (int i = 0; i < 6; i++) {
                float fi = float(i);
                vec2 center = vec2(0.5 + 0.35 * sin(t + fi * 1.1), 0.5 + 0.35 * cos(t * 0.8 + fi * 0.9));
                float dist = length(sampleUV - center);
                vec3 col = vec3(0.18 + fi * 0.08, 0.6 - fi * 0.05, 0.75 - fi * 0.08);
                sample_bg += col * 0.25 * smoothstep(0.3, 0.0, dist);
            }
            glassColor += sample_bg * w;
            total += w;
        }
    }
    glassColor /= total;

    // Glass tint
    glassColor = mix(glassColor, glassColor * vec3(0.95, 0.98, 1.0), 0.3);

    // Edge highlight
    float edgeGlow = smoothstep(8.0, 0.0, abs(d)) * 0.15;
    glassColor += vec3(1.0) * edgeGlow;

    // Blend
    vec3 finalColor = mix(bg, glassColor, mask);

    gl_FragColor = vec4(finalColor, 1.0);
}
